import os # Use deterministic headless scientific plotting for actual native time histories.
os.environ['MPLBACKEND']='Agg';os.environ['OPENBLAS_NUM_THREADS']='1' # Bound rendering resources while actual native qualification runs continue.
import argparse,csv,json # Preserve exact plotted numerical data and its source identities.
from pathlib import Path # Keep figures beside their physical-family evidence.
import numpy as np # Integrate every retained actual thermal and plastic field.
import matplotlib.pyplot as plt # Render standard exportable scientific curves without synthetic contours.
from complex_thermoplastic_checks import quadrature,tensor # Reuse exact native C3D10 quadrature and documented six-component tensor ordering.
from complex_thermoplastic import sha,write_json # Record exact full-field source hashes for independent reproduction.
def render(folder,output): # Plot a completed full-order native trajectory without any neural or fabricated values.
    folder=Path(folder);output=Path(output);output.mkdir(parents=True,exist_ok=True);a=dict(np.load(folder/'fields.npz'));m=json.loads((folder/'metadata.json').read_text());receipt=json.loads((folder/'receipt.json').read_text());assert receipt['quality']=='VALID_CONVERGED';s=a['states'];n=m['node_count'];e=m['element_count'];_,volume,shape=quadrature(a['fe_xyz'],a['tet']);weights=np.repeat(volume/4.,4);weights/=weights.sum();temperature_ip=np.einsum('qj,tej->teq',shape,s[:,a['tet'],3]).reshape(len(s),-1);q=np.linalg.norm(s[:,n:,23:26],axis=-1);p=s[:,n:,10];plastic_inverse=np.eye(3)-2.*tensor(s[:,n:,11:17]);drift=np.abs(np.linalg.det(plastic_inverse)-1.).max(axis=1);times=a['controls'][:,0] # Evaluate real volume statistics over all actual native elements and integration points.
    data=np.column_stack([times,s[:,:n,3].min(axis=1),temperature_ip@weights,s[:,:n,3].max(axis=1),np.sqrt(q**2@weights),q.max(axis=1),p@weights,p.max(axis=1),drift,a['controls'][:,2]]);names=['time_s','temperature_min_C','temperature_volume_mean_C','temperature_max_C','heat_flux_volume_RMS_kW_per_m2','heat_flux_max_kW_per_m2','peeq_volume_mean','peeq_max','plastic_inverse_metric_determinant_max_error','right_ux_mm'] # In theN-mm-s unit system native heat-flux numbers equalkW/m2; no arbitrary rescaling is applied.
    with (output/'native_thermoplastic_history.csv').open('w',newline='') as handle: writer=csv.writer(handle);writer.writerow(names);writer.writerows(data.tolist()) # Export every exact plotted value for review and reuse.
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.titleweight':'bold','figure.facecolor':'white','axes.facecolor':'#f7f9fc'});fig,axes=plt.subplots(2,2,figsize=(12,8),constrained_layout=True);blue='#1668ac';orange='#d8642a';green='#13866b' # Use restrained consistent styling with sufficient contrast for a technical report.
    ax=axes[0,0];ax.plot(times,data[:,1],color='#8a98a8',label='Minimum node temperature');ax.plot(times,data[:,2],color=blue,lw=2,label='Volume mean');ax.plot(times,data[:,3],color=orange,lw=2,label='Maximum node temperature');ax.set(title='Actual transient temperature',ylabel='Temperature (C)');ax.legend(frameon=False,fontsize=8) # Distinguish internal transient response from prescribed boundary extrema.
    ax=axes[0,1];ax.plot(times,data[:,4],color=blue,lw=2,label='Volume RMS');ax.plot(times,data[:,5],color=orange,lw=1.8,label='Maximum actual IP magnitude');ax.set(title='Native integration-point heat flux',ylabel='Heat flux (kW/m2)');ax.legend(frameon=False,fontsize=8) # Use genuine nativeHFL vectors rather than inferring flux from summary temperatures.
    ax=axes[1,0];ax.plot(times,data[:,6],color=green,lw=2,label='Volume mean PEEQ');ax.plot(times,data[:,7],color=orange,lw=2,label='Maximum actual IP PEEQ');ax.set(title='Irreversible plastic history',ylabel='Accumulated plastic strain');ax.legend(frameon=False,fontsize=8) # Preserve loading, unloading and reversal history without resetting accumulated plasticity.
    ax=axes[1,1];ax.plot(times,100.*data[:,8],color='#843d91',lw=2);ax.set(title='Disclosed native plastic-metric drift',ylabel='max |det(inverse Cp) - 1| (%)') # Show the uncorrected native integration diagnostic rather than projecting it away.
    for ax in axes.ravel(): ax.set_xlabel('Physical time (s)');ax.grid(True,color='#d8dee8',lw=.6,alpha=.8);ax.margins(x=.02) # Keep physical time and readable scales consistent across all panels.
    fig.suptitle(f'Full-order thermoplastic history: {m["id"]}\n{n:,} nodes + {4*e:,} actual IPs; one-way heat-to-mechanics coupling',fontsize=14,fontweight='bold');fig.savefig(output/'native_thermoplastic_history.png',dpi=180);fig.savefig(output/'native_thermoplastic_history.pdf');plt.close(fig) # Save reproducible standalone scientific artifacts from actual solved fields.
    write_json(output/'native_thermoplastic_history_sources.json',{'case':str(folder),'fields_npz_sha256':sha(folder/'fields.npz'),'metadata_sha256':sha(folder/'metadata.json'),'native_receipt_sha256':sha(folder/'receipt.json'),'values_csv':str(output/'native_thermoplastic_history.csv'),'entity_coverage':'Every source FE node and actual integration point; true element-volume quadrature for averages.','thermal_coupling':'One-way actual transient heat PDE to temperature-dependent finite-strain mechanics; plastic-dissipation heat feedback is not implemented.','qualification_note':'The figure is a solver-backed single-history result; global family mesh/time release and held-out neural accuracy are separate evidence.','plastic_metric_note':'Native storedSDV2:7 reconstruct inverseCp; visible isochoric drift is retained without projection.'}) # Keep plot provenance and physical limitations explicit without inventing additional solved mechanisms.
if __name__=='__main__': # Render only an explicitly selected completed native reference history.
    parser=argparse.ArgumentParser();parser.add_argument('case');parser.add_argument('output');args=parser.parse_args();render(args.case,args.output) # Avoid loading any held-out learning labels for a convenience figure.
